//! Speech model catalog (plan section 9.1).
//!
//! `models.json` is generated by scripts/gen-model-manifest.py on a CI
//! runner and embedded at build time. Every file URL is pinned to a commit
//! and carries its size and SHA-256.

use super::engine::{Family, ModelFiles};
use super::manager::ModelSpec;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

const MANIFEST: &str = include_str!("../../../models.json");

/// The default model and the small-RAM fallback (plan P4.4).
pub const DEFAULT_MODEL: &str = "parakeet-110m";
pub const SMALL_RAM_MODEL: &str = "moonshine-tiny-en";
/// Below this much RAM `auto` picks the small model.
pub const SMALL_RAM_BYTES: u64 = 6 * 1024 * 1024 * 1024;
/// File written after every file of a model passed its hash check.
pub const VERIFIED_MARKER: &str = ".verified";

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq, Eq)]
pub struct FileEntry {
    pub name: String,
    pub url: String,
    pub size: u64,
    pub sha256: String,
}

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq, Eq)]
pub struct ModelEntry {
    pub name: String,
    pub family: String,
    pub languages: Vec<String>,
    pub license: String,
    #[serde(default)]
    pub legacy: bool,
    pub repo: String,
    pub revision: String,
    pub files: Vec<FileEntry>,
}

impl ModelEntry {
    pub fn total_size(&self) -> u64 {
        self.files.iter().map(|f| f.size).sum()
    }

    pub fn family(&self) -> Option<Family> {
        Family::parse(&self.family)
    }
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct Manifest {
    pub schema: u32,
    pub vad: Option<FileEntry>,
    pub models: BTreeMap<String, ModelEntry>,
}

pub fn manifest() -> Result<Manifest, String> {
    serde_json::from_str(MANIFEST).map_err(|e| format!("models.json: {e}"))
}

/// Models offered to the user (legacy entries are only recognised).
pub fn offered(m: &Manifest) -> Vec<(&String, &ModelEntry)> {
    m.models.iter().filter(|(_, e)| !e.legacy).collect()
}

/// Turn a `speech_model` setting into a model id. `auto` resolves by RAM;
/// removed or unknown ids map to `auto` (P4.6).
pub fn resolve_id(setting: &str, total_ram: Option<u64>, m: &Manifest) -> String {
    let wanted = match setting {
        "auto" | "" | "parakeet-0.6b" => None,
        id if m.models.get(id).is_some_and(|e| !e.legacy) => Some(id.to_string()),
        _ => None,
    };
    wanted.unwrap_or_else(|| auto_choice(total_ram, m))
}

pub fn auto_choice(total_ram: Option<u64>, m: &Manifest) -> String {
    let small = total_ram.is_some_and(|r| r < SMALL_RAM_BYTES);
    if small && m.models.contains_key(SMALL_RAM_MODEL) {
        SMALL_RAM_MODEL.to_string()
    } else {
        DEFAULT_MODEL.to_string()
    }
}

/// Where a model's files live.
pub fn model_dir(models_dir: &Path, id: &str) -> PathBuf {
    models_dir.join(id)
}

/// Installed means every file matches the manifest size and the marker
/// written after the hash check is present (P4.3).
pub fn is_installed(dir: &Path, entry: &ModelEntry) -> bool {
    dir.join(VERIFIED_MARKER).is_file()
        && entry.files.iter().all(|f| {
            std::fs::metadata(dir.join(&f.name))
                .map(|m| m.len() == f.size)
                .unwrap_or(false)
        })
}

/// Contents of the marker: one `name size sha256` line per file, so a
/// manifest change invalidates old installs.
pub fn marker_text(entry: &ModelEntry) -> String {
    entry
        .files
        .iter()
        .map(|f| format!("{} {} {}\n", f.name, f.size, f.sha256))
        .collect()
}

pub fn marker_matches(dir: &Path, entry: &ModelEntry) -> bool {
    std::fs::read_to_string(dir.join(VERIFIED_MARKER)).is_ok_and(|t| t == marker_text(entry))
}

/// Build a loadable spec for an installed model.
pub fn spec(models_dir: &Path, id: &str, m: &Manifest) -> Result<ModelSpec, String> {
    let entry = m
        .models
        .get(id)
        .ok_or_else(|| format!("unknown speech model {id}"))?;
    let family = entry
        .family()
        .ok_or_else(|| format!("unknown model family {}", entry.family))?;
    let dir = model_dir(models_dir, id);
    if !is_installed(&dir, entry) || !marker_matches(&dir, entry) {
        return Err(format!(
            "The {} speech model is not downloaded. Open LocalYapper to download it.",
            entry.name
        ));
    }
    let names: Vec<&str> = entry.files.iter().map(|f| f.name.as_str()).collect();
    Ok(ModelSpec {
        id: id.to_string(),
        family,
        files: ModelFiles::from_names(family, &dir, &names)?,
    })
}

/// The folder name earlier versions used for Parakeet 110M.
pub const LEGACY_DIR: &str = "parakeet-tdt-ctc-110m";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn manifest_is_complete_and_pinned() {
        let m = manifest().expect("manifest parses");
        assert!(m.models.contains_key(DEFAULT_MODEL));
        for (id, e) in &m.models {
            assert!(e.family().is_some(), "{id}: family");
            assert!(!e.files.is_empty(), "{id}: files");
            for f in &e.files {
                assert!(
                    f.url.contains(&e.revision),
                    "{id}/{}: URL not pinned",
                    f.name
                );
                assert_eq!(f.sha256.len(), 64, "{id}/{}: sha256", f.name);
                assert!(f.size > 0);
            }
            let names: Vec<&str> = e.files.iter().map(|f| f.name.as_str()).collect();
            assert!(
                ModelFiles::from_names(e.family().expect("family"), Path::new("/m"), &names)
                    .is_ok(),
                "{id}: files do not form a loadable model"
            );
        }
        let vad = m.vad.expect("vad entry");
        assert_eq!(vad.name, "silero_vad.onnx");
    }

    #[test]
    fn auto_resolves_by_ram_and_old_ids_map_to_auto() {
        let m = manifest().expect("manifest");
        let gib = 1024 * 1024 * 1024;
        assert_eq!(resolve_id("auto", Some(16 * gib), &m), DEFAULT_MODEL);
        if m.models.contains_key(SMALL_RAM_MODEL) {
            assert_eq!(resolve_id("auto", Some(4 * gib), &m), SMALL_RAM_MODEL);
        }
        assert_eq!(
            resolve_id("parakeet-0.6b", Some(16 * gib), &m),
            DEFAULT_MODEL
        );
        assert_eq!(resolve_id("whisper-large", None, &m), DEFAULT_MODEL);
        assert_eq!(resolve_id(DEFAULT_MODEL, Some(2 * gib), &m), DEFAULT_MODEL);
    }

    #[test]
    fn installed_needs_sizes_and_marker() {
        let m = manifest().expect("manifest");
        let entry = &m.models[DEFAULT_MODEL];
        let dir = std::env::temp_dir().join(format!("ly-catalog-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("dir");
        assert!(!is_installed(&dir, entry));
        for f in &entry.files {
            let file = std::fs::File::create(dir.join(&f.name)).expect("create");
            file.set_len(f.size).expect("sparse size");
        }
        assert!(!is_installed(&dir, entry), "no marker yet");
        std::fs::write(dir.join(VERIFIED_MARKER), marker_text(entry)).expect("marker");
        assert!(is_installed(&dir, entry));
        assert!(marker_matches(&dir, entry));
        let first = &entry.files[0];
        let file = std::fs::OpenOptions::new()
            .write(true)
            .open(dir.join(&first.name))
            .expect("open");
        file.set_len(first.size - 1).expect("truncate");
        assert!(!is_installed(&dir, entry), "truncated file");
        let _ = std::fs::remove_dir_all(&dir);
    }
}
